{
  "name": "KnowSense AI",
  "description": "An Autonomous Knowledge Extractor that transforms unstructured content into structured learning materials, exam papers, or summaries based on your persona."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum UserMode {
  GENERAL = 'General',
  STUDENT = 'Student',
  EXAMINER = 'Examiner',
}

export interface Concept {
  title: string;
  description: string;
}

export interface Question {
  id: string;
  text: string;
  answer: string;
  difficulty: 'Easy' | 'Medium' | 'Hard';
  priority?: 'High' | 'Medium' | 'Low'; // Student mode specific
  marks?: number; // Examiner mode specific
  topicRef?: string;
}

export interface KnowSenseResponse {
  summary: string;
  concepts: Concept[];
  questions: Question[];
  coverageAnalysis?: string; // Examiner mode specific
}

export interface Session {
  id: string;
  title: string;
  timestamp: number;
  mode: UserMode;
  data: KnowSenseResponse | null;
  history: { role: 'user' | 'model'; text: string }[];
}

export interface ProcessingState {
  status: 'idle' | 'processing' | 'success' | 'error';
  message?: string;
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { UserMode, KnowSenseResponse } from "../types";

const SYSTEM_INSTRUCTION = `
You are KnowSense AI, an advanced Autonomous Knowledge Extractor and Educational Agent.
Your goal is to analyze unstructured input (text or images) and transform it into structured, high-quality educational content based on the user's selected mode.

### AGENT PIPELINE
1. **Input Normalization**: Clean and understand the core text or visual content.
2. **Knowledge Extraction**: Identify key concepts, definitions, and relationships.
3. **Question Generation**: Create questions with varying depth based on the mode.
4. **Answer Generation**: Write clear, concise, and accurate answers.
5. **Classification**: Assign difficulty (Easy, Medium, Hard) based on Bloom's Taxonomy.
6. **Mode Adaptation**:
    - **GENERAL MODE**: Balanced mix of concepts and questions. Explanations should be simple and accessible.
    - **STUDENT MODE**: Focus on "Need to Know". High priority items first. Short, memorable answers. Ranking questions by importance.
    - **EXAMINER MODE**: Structured like a test paper. Assign marks. Ensure coverage of different topics. detailed marking keys.

### OUTPUT FORMAT
Return purely JSON matching the provided schema. Do not include markdown code blocks.
`;

const RESPONSE_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    summary: {
      type: Type.STRING,
      description: "A concise executive summary of the content (max 3 sentences).",
    },
    concepts: {
      type: Type.ARRAY,
      description: "Key concepts extracted from the material.",
      items: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          description: { type: Type.STRING, description: "Clear, simple definition." },
        },
        required: ["title", "description"],
      },
    },
    questions: {
      type: Type.ARRAY,
      description: "Generated questions based on the content.",
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING, description: "Unique ID (e.g., Q1)" },
          text: { type: Type.STRING, description: "The question text." },
          answer: { type: Type.STRING, description: "The model answer." },
          difficulty: { type: Type.STRING, enum: ["Easy", "Medium", "Hard"] },
          priority: { type: Type.STRING, enum: ["High", "Medium", "Low"], description: "Relevance for students." },
          marks: { type: Type.INTEGER, description: "Suggested marks for examiners." },
          topicRef: { type: Type.STRING, description: "Which concept this relates to." },
        },
        required: ["id", "text", "answer", "difficulty"],
      },
    },
    coverageAnalysis: {
      type: Type.STRING,
      description: "Brief analysis of what topics are covered (mostly for Examiner mode).",
    },
  },
  required: ["summary", "concepts", "questions"],
};

export const generateKnowSenseResponse = async (
  content: string,
  mode: UserMode,
  imageBase64?: string
): Promise<KnowSenseResponse> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const promptText = `
    Analyze the following content in **${mode.toUpperCase()} MODE**.

    Content:
    ${content}

    ${imageBase64 ? "[Attached Image Provided]" : ""}
  `;

  const parts: any[] = [{ text: promptText }];

  if (imageBase64) {
    // Basic stripping of data url prefix if present
    const base64Data = imageBase64.split(',')[1] || imageBase64;
    parts.push({
      inlineData: {
        mimeType: "image/jpeg", // Assuming JPEG for simplicity in this demo, usually detected from file
        data: base64Data,
      },
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-latest", // Good balance of speed and reasoning
      contents: { parts },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: RESPONSE_SCHEMA,
        temperature: 0.3, // Lower temperature for more structured/factual output
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text) as KnowSenseResponse;

  } catch (error) {
    console.error("KnowSense AI Error:", error);
    throw error;
  }
};

import React from 'react';
