import React from 'react';
import { Share2, ChevronDown, User, GraduationCap, FileCheck } from 'lucide-react';
import { UserMode } from '../types';

interface TopBarProps {
  mode: UserMode;
  onModeChange: (mode: UserMode) => void;
}

export const TopBar: React.FC<TopBarProps> = ({ mode, onModeChange }) => {
  const [isDropdownOpen, setIsDropdownOpen] = React.useState(false);
  const dropdownRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const getModeIcon = (m: UserMode) => {
    switch (m) {
      case UserMode.STUDENT: return <GraduationCap size={16} />;
      case UserMode.EXAMINER: return <FileCheck size={16} />;
      default: return <User size={16} />;
    }
  };

  const getModeColor = (m: UserMode) => {
    switch (m) {
      case UserMode.STUDENT: return 'text-blue-600 bg-blue-50';
      case UserMode.EXAMINER: return 'text-purple-600 bg-purple-50';
      default: return 'text-gray-700 bg-gray-100';
    }
  };

  return (
    <div className="h-14 border-b border-gray-200 flex items-center justify-between px-6 bg-white sticky top-0 z-10">
      <div className="flex items-center text-gray-500 text-sm font-medium">
        <button className="flex items-center gap-2 hover:text-gray-900 transition-colors">
          <Share2 size={16} />
          <span className="hidden sm:inline">Share</span>
        </button>
      </div>

      <div className="relative" ref={dropdownRef}>
        <button
          onClick={() => setIsDropdownOpen(!isDropdownOpen)}
          className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all border border-transparent hover:border-gray-200 hover:shadow-sm ${getModeColor(mode)}`}
        >
          {getModeIcon(mode)}
          <span>{mode} Mode</span>
          <ChevronDown size={14} className={`transform transition-transform ${isDropdownOpen ? 'rotate-180' : ''}`} />
        </button>

        {isDropdownOpen && (
          <div className="absolute right-0 top-full mt-2 w-56 bg-white border border-gray-200 rounded-lg shadow-lg py-1 z-20 animate-in fade-in zoom-in-95 duration-100">
            {Object.values(UserMode).map((m) => (
              <button
                key={m}
                onClick={() => {
                  onModeChange(m);
                  setIsDropdownOpen(false);
                }}
                className={`w-full text-left px-4 py-2.5 text-sm flex items-center gap-3 hover:bg-gray-50 ${mode === m ? 'bg-gray-50 font-medium text-gray-900' : 'text-gray-600'}`}
              >
                <div className={`p-1 rounded ${mode === m ? 'bg-white shadow-sm' : ''}`}>
                   {getModeIcon(m)}
                </div>
                {m} Mode
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useRef, useState } from 'react';
import { ArrowUp, Image as ImageIcon, X, Paperclip } from 'lucide-react';
import { ProcessingState } from '../types';

interface InputBarProps {
  onSend: (text: string, image?: File) => void;
  processingState: ProcessingState;
}

export const InputBar: React.FC<InputBarProps> = ({ onSend, processingState }) => {
  const [text, setText] = useState('');
  const [image, setImage] = useState<File | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit();
    }
  };

  const handleSubmit = () => {
    if ((!text.trim() && !image) || processingState.status === 'processing') return;
    onSend(text, image || undefined);
    setText('');
    setImage(null);
    if (textareaRef.current) {
        textareaRef.current.style.height = 'auto';
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setImage(e.target.files[0]);
    }
  };

  const adjustHeight = (e: React.FormEvent<HTMLTextAreaElement>) => {
    const target = e.currentTarget;
    target.style.height = 'auto';
    target.style.height = `${Math.min(target.scrollHeight, 200)}px`;
  };

  return (
    <div className="w-full max-w-3xl mx-auto p-4 mb-4">
      {/* File Preview */}
      {image && (
        <div className="mb-2 inline-flex items-center gap-2 bg-gray-100 px-3 py-1.5 rounded-full text-xs font-medium text-gray-700 animate-in fade-in slide-in-from-bottom-2">
          <ImageIcon size={14} />
          <span className="max-w-[150px] truncate">{image.name}</span>
          <button 
            onClick={() => setImage(null)}
            className="hover:bg-gray-200 rounded-full p-0.5"
          >
            <X size={12} />
          </button>
        </div>
      )}

      {/* Input Box */}
      <div className={`relative bg-white border shadow-sm rounded-xl transition-all ${processingState.status === 'processing' ? 'border-gray-200 opacity-75' : 'border-gray-300 hover:border-gray-400 focus-within:ring-2 focus-within:ring-gray-100 focus-within:border-gray-400'}`}>
        <textarea
            ref={textareaRef}
            value={text}
            onChange={(e) => { setText(e.target.value); adjustHeight(e); }}
            onKeyDown={handleKeyDown}
            placeholder="Paste text, notes, or ask a question..."
            rows={1}
            disabled={processingState.status === 'processing'}
            className="w-full px-4 py-3.5 pr-12 bg-transparent resize-none outline-none text-gray-800 placeholder-gray-400 min-h-[52px] max-h-[200px]"
        />

        <div className="absolute bottom-2.5 right-2 flex items-center gap-1">
             <input
                type="file"
                ref={fileInputRef}
                onChange={handleFileChange}
                accept="image/*"
                className="hidden"
            />
             <button
                onClick={() => fileInputRef.current?.click()}
                disabled={processingState.status === 'processing'}
                className="p-2 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-lg transition-colors"
                title="Attach Image"
            >
                <Paperclip size={18} />
            </button>

            <button
                onClick={handleSubmit}
                disabled={(!text.trim() && !image) || processingState.status === 'processing'}
                className={`p-2 rounded-lg transition-all ${
                    (!text.trim() && !image) || processingState.status === 'processing'
                    ? 'bg-gray-100 text-gray-300' 
                    : 'bg-black text-white hover:bg-gray-800 shadow-sm'
                }`}
            >
                <ArrowUp size={18} />
            </button>
        </div>
      </div>
      <div className="text-center mt-2">
         <p className="text-[10px] text-gray-400">AI can make mistakes. Check important info.</p>
      </div>
    </div>
  );
};

import React from 'react';
import { KnowSenseResponse, UserMode, Question, Concept } from '../types';
import { Book, AlertCircle, CheckCircle, Tag, Brain, List } from 'lucide-react';

interface OutputRendererProps {
  data: KnowSenseResponse;
  mode: UserMode;
}

export const OutputRenderer: React.FC<OutputRendererProps> = ({ data, mode }) => {

  const DifficultyBadge = ({ level }: { level: string }) => {
    const colors = {
      Easy: 'bg-green-100 text-green-700 border-green-200',
      Medium: 'bg-yellow-100 text-yellow-700 border-yellow-200',
      Hard: 'bg-red-100 text-red-700 border-red-200',
    };
    return (
      <span className={`text-[10px] font-semibold px-2 py-0.5 rounded-full border ${colors[level as keyof typeof colors] || colors.Medium}`}>
        {level}
      </span>
    );
  };

  const PriorityBadge = ({ level }: { level: string }) => {
    if (!level) return null;
    const colors = {
        High: 'text-red-600 bg-red-50',
        Medium: 'text-orange-600 bg-orange-50',
        Low: 'text-gray-500 bg-gray-50',
    };
    return (
        <span className={`text-[10px] uppercase tracking-wider font-bold ml-2 px-1.5 rounded ${colors[level as keyof typeof colors]}`}>
            {level} Priority
        </span>
    );
  };

  return (
    <div className="max-w-3xl mx-auto pb-24 animate-in fade-in slide-in-from-bottom-4 duration-500">

      {/* Header Summary */}
      <div className="mb-10">
        <h1 className="text-3xl font-bold text-gray-900 mb-4 tracking-tight">Analysis Result</h1>
        <div className="p-5 bg-gray-50 border border-gray-100 rounded-xl">
          <div className="flex items-start gap-3">
            <Brain className="text-gray-400 mt-1 shrink-0" size={20} />
            <p className="text-gray-700 leading-relaxed text-base">{data.summary}</p>
          </div>
        </div>
      </div>

      {/* Concepts Grid */}
      <div className="mb-12">
        <div className="flex items-center gap-2 mb-4">
            <Book className="text-gray-400" size={18} />
            <h2 className="text-lg font-semibold text-gray-800">Key Concepts</h2>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {data.concepts.map((concept, idx) => (
            <div key={idx} className="p-4 border border-gray-200 rounded-lg hover:shadow-md transition-shadow bg-white">
              <h3 className="font-semibold text-gray-900 mb-2 flex items-center gap-2">
                {concept.title}
              </h3>
              <p className="text-sm text-gray-600 leading-relaxed">{concept.description}</p>
            </div>
          ))}
        </div>
      </div>

      {/* Questions Section - Mode Specific Layout */}
      <div>
        <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-2">
                <List className="text-gray-400" size={18} />
                <h2 className="text-lg font-semibold text-gray-800">
                    {mode === UserMode.EXAMINER ? 'Generated Assessment' : 'Practice Questions'}
                </h2>
            </div>
            {mode === UserMode.EXAMINER && (
                <span className="text-xs font-mono text-gray-500 bg-gray-100 px-2 py-1 rounded">
                    Total Questions: {data.questions.length}
                </span>
            )}
        </div>

        <div className="space-y-6">
          {data.questions.map((q, idx) => (
            <div key={idx} className="group border border-gray-200 rounded-xl overflow-hidden bg-white transition-all hover:border-gray-300">
              {/* Question Header */}
              <div className="p-4 bg-white border-b border-gray-50 flex flex-col sm:flex-row sm:items-start gap-3 justify-between">
                <div className="flex-1">
                   <div className="flex items-center gap-2 mb-1.5">
                        <span className="text-xs font-mono text-gray-400">#{q.id}</span>
                        <DifficultyBadge level={q.difficulty} />
                        {mode === UserMode.STUDENT && q.priority && <PriorityBadge level={q.priority} />}
                        {mode === UserMode.EXAMINER && q.marks && (
                            <span className="text-xs font-bold text-gray-600 bg-gray-100 px-1.5 rounded">
                                {q.marks} Marks
                            </span>
                        )}
                   </div>
                   <h3 className="text-base font-medium text-gray-900 leading-snug">{q.text}</h3>
                </div>
              </div>

              {/* Answer Section */}
              <div className="px-4 py-3 bg-gray-50/50 group-hover:bg-gray-50 transition-colors">
                <div className="flex items-start gap-2">
                    <div className="mt-0.5 min-w-[16px]">
                        {mode === UserMode.EXAMINER ? (
                            <CheckCircle size={14} className="text-green-600" />
                        ) : (
                            <AlertCircle size={14} className="text-blue-500" />
                        )}
                    </div>
                    <div>
                        <p className="text-xs uppercase tracking-wide text-gray-400 font-bold mb-1">
                            {mode === UserMode.EXAMINER ? 'Marking Key' : 'Answer'}
                        </p>
                        <p className="text-sm text-gray-700">{q.answer}</p>
                    </div>
                </div>
              </div>

              {/* Footer Meta (Topic ref) */}
              {q.topicRef && (
                  <div className="px-4 py-2 border-t border-gray-100 bg-white flex items-center gap-1.5">
                      <Tag size={12} className="text-gray-400" />
                      <span className="text-xs text-gray-500">Relates to: {q.topicRef}</span>
                  </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* Examiner Coverage Analysis */}
      {mode === UserMode.EXAMINER && data.coverageAnalysis && (
          <div className="mt-12 p-5 border border-purple-100 bg-purple-50/30 rounded-xl">
              <h3 className="text-sm font-bold text-purple-900 mb-2 uppercase tracking-wide">Coverage Analysis</h3>
              <p className="text-sm text-purple-800">{data.coverageAnalysis}</p>
          </div>
      )}

    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { TopBar } from './components/TopBar';
import { InputBar } from './components/InputBar';
import { OutputRenderer } from './components/OutputRenderer';
import { UserMode, Session, ProcessingState, KnowSenseResponse } from './types';
import { generateKnowSenseResponse } from './services/gemini';
import { Loader2, Sparkles, AlertTriangle } from 'lucide-react';

const App: React.FC = () => {
  const [mode, setMode] = useState<UserMode>(UserMode.GENERAL);
  const [sessions, setSessions] = useState<Session[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [processingState, setProcessingState] = useState<ProcessingState>({ status: 'idle' });

  // Load from local storage on mount (mock persistence)
  useEffect(() => {
    const saved = localStorage.getItem('knowsense_sessions');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setSessions(parsed);
        if (parsed.length > 0) setCurrentSessionId(parsed[0].id);
      } catch (e) {
        console.error("Failed to load history", e);
      }
    }
  }, []);

  // Save to local storage on change
  useEffect(() => {
    localStorage.setItem('knowsense_sessions', JSON.stringify(sessions));
  }, [sessions]);

  const handleNewSession = () => {
    setCurrentSessionId(null);
    setProcessingState({ status: 'idle' });
  };

  const handleSelectSession = (id: string) => {
    setCurrentSessionId(id);
    setProcessingState({ status: 'success' }); // Assume loaded sessions are successful
  };

  const getCurrentSession = () => sessions.find(s => s.id === currentSessionId);

  const handleSend = async (text: string, image?: File) => {
    setProcessingState({ status: 'processing', message: 'Analyzing content...' });

    // Create optimistic session if new
    let sessionId = currentSessionId;
    if (!sessionId) {
      sessionId = Date.now().toString();
      const newSession: Session = {
        id: sessionId,
        title: text.slice(0, 30) || 'Image Analysis',
        timestamp: Date.now(),
        mode: mode,
        data: null,
        history: [{ role: 'user', text: text || '[Image Uploaded]' }]
      };
      setSessions(prev => [newSession, ...prev]);
      setCurrentSessionId(sessionId);
    }

    try {
      let imageBase64: string | undefined;
      if (image) {
        imageBase64 = await new Promise((resolve) => {
          const reader = new FileReader();
          reader.onloadend = () => resolve(reader.result as string);
          reader.readAsDataURL(image);
        });
      }

      // Simulate multi-step pipeline messages for UX
      setTimeout(() => setProcessingState(p => ({ ...p, message: 'Extracting knowledge graph...' })), 1500);
      setTimeout(() => setProcessingState(p => ({ ...p, message: `Generating ${mode.toLowerCase()} materials...` })), 3000);

      const result = await generateKnowSenseResponse(text, mode, imageBase64);

      // Update session with result
      setSessions(prev => prev.map(s => {
        if (s.id === sessionId) {
          return {
            ...s,
            data: result,
            title: result.summary.slice(0, 40) + "..." // Update title based on AI summary
          };
        }
        return s;
      }));
      setProcessingState({ status: 'success' });

    } catch (error) {
      console.error(error);
