import { GoogleGenAI, Type, Schema } from "@google/genai";
import { UserMode, KnowSenseResponse } from "../types";

const SYSTEM_INSTRUCTION = `
You are KnowSense AI, an advanced Autonomous Knowledge Extractor and Educational Agent.
Your goal is to analyze unstructured input (text or images) and transform it into structured, high-quality educational content based on the user's selected mode.

### AGENT PIPELINE
1. **Input Normalization**: Clean and understand the core text or visual content.
2. **Knowledge Extraction**: Identify key concepts, definitions, and relationships.
3. **Question Generation**: Create questions with varying depth based on the mode.
4. **Answer Generation**: Write clear, concise, and accurate answers.
5. **Classification**: Assign difficulty (Easy, Medium, Hard) based on Bloom's Taxonomy.
6. **Mode Adaptation**:
    - **GENERAL MODE**: Balanced mix of concepts and questions. Explanations should be simple and accessible.
    - **STUDENT MODE**: Focus on "Need to Know". High priority items first. Short, memorable answers. Ranking questions by importance.
    - **EXAMINER MODE**: Structured like a test paper. Assign marks. Ensure coverage of different topics. detailed marking keys.

### OUTPUT FORMAT
Return purely JSON matching the provided schema. Do not include markdown code blocks.
`;

const RESPONSE_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    summary: {
      type: Type.STRING,
      description: "A concise executive summary of the content (max 3 sentences).",
    },
    concepts: {
      type: Type.ARRAY,
      description: "Key concepts extracted from the material.",
      items: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          description: { type: Type.STRING, description: "Clear, simple definition." },
        },
        required: ["title", "description"],
      },
    },
    questions: {
      type: Type.ARRAY,
      description: "Generated questions based on the content.",
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING, description: "Unique ID (e.g., Q1)" },
          text: { type: Type.STRING, description: "The question text." },
          answer: { type: Type.STRING, description: "The model answer." },
          difficulty: { type: Type.STRING, enum: ["Easy", "Medium", "Hard"] },
          priority: { type: Type.STRING, enum: ["High", "Medium", "Low"], description: "Relevance for students." },
          marks: { type: Type.INTEGER, description: "Suggested marks for examiners." },
          topicRef: { type: Type.STRING, description: "Which concept this relates to." },
        },
        required: ["id", "text", "answer", "difficulty"],
      },
    },
    coverageAnalysis: {
      type: Type.STRING,
      description: "Brief analysis of what topics are covered (mostly for Examiner mode).",
    },
  },
  required: ["summary", "concepts", "questions"],
};

export const generateKnowSenseResponse = async (
  content: string,
  mode: UserMode,
  imageBase64?: string
): Promise<KnowSenseResponse> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const promptText = `
    Analyze the following content in **${mode.toUpperCase()} MODE**.

    Content:
    ${content}

    ${imageBase64 ? "[Attached Image Provided]" : ""}
  `;

  const parts: any[] = [{ text: promptText }];

  if (imageBase64) {
    // Basic stripping of data url prefix if present
    const base64Data = imageBase64.split(',')[1] || imageBase64;
    parts.push({
      inlineData: {
        mimeType: "image/jpeg", // Assuming JPEG for simplicity in this demo, usually detected from file
        data: base64Data,
      },
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: { parts },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: RESPONSE_SCHEMA,
        temperature: 0.3, // Lower temperature for more structured/factual output
      },
    });

    let text = response.text;
    if (!text) throw new Error("No response from AI");

    // Robustly strip markdown if the model includes it
    text = text.trim();
    if (text.startsWith("```json")) {
      text = text.replace(/^```json\s*/, "").replace(/\s*```$/, "");
    } else if (text.startsWith("```")) {
      text = text.replace(/^```\s*/, "").replace(/\s*```$/, "");
    }

    return JSON.parse(text) as KnowSenseResponse;

  } catch (error) {
    console.error("KnowSense AI Error:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Sidebar } from './components/Sidebar';
import { TopBar } from './components/TopBar';
import { InputBar } from './components/InputBar';
import { OutputRenderer } from './components/OutputRenderer';
import { UserMode, Session, ProcessingState, KnowSenseResponse } from './types';
import { generateKnowSenseResponse } from './services/gemini';
import { Loader2, Sparkles, AlertTriangle } from 'lucide-react';

const App: React.FC = () => {
  const [mode, setMode] = useState<UserMode>(UserMode.GENERAL);
  const [sessions, setSessions] = useState<Session[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [processingState, setProcessingState] = useState<ProcessingState>({ status: 'idle' });

  const timersRef = useRef<NodeJS.Timeout[]>([]);

  // Load from local storage on mount (mock persistence)
  useEffect(() => {
    const saved = localStorage.getItem('knowsense_sessions');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setSessions(parsed);
        if (parsed.length > 0) setCurrentSessionId(parsed[0].id);
      } catch (e) {
        console.error("Failed to load history", e);
      }
    }
  }, []);

  // Save to local storage on change
  useEffect(() => {
    localStorage.setItem('knowsense_sessions', JSON.stringify(sessions));
  }, [sessions]);

  // Clean up timers on unmount
  useEffect(() => {
    return () => {
      timersRef.current.forEach(clearTimeout);
    };
  }, []);

  const clearTimers = () => {
    timersRef.current.forEach(clearTimeout);
    timersRef.current = [];
  };

  const handleNewSession = () => {
    setCurrentSessionId(null);
    setProcessingState({ status: 'idle' });
    clearTimers();
  };

  const handleSelectSession = (id: string) => {
    setCurrentSessionId(id);
    setProcessingState({ status: 'success' }); // Assume loaded sessions are successful
    clearTimers();
  };

  const getCurrentSession = () => sessions.find(s => s.id === currentSessionId);

  const handleSend = async (text: string, image?: File) => {
    clearTimers();
    setProcessingState({ status: 'processing', message: 'Analyzing content...' });

    // Create optimistic session if new
    let sessionId = currentSessionId;
    if (!sessionId) {
      sessionId = Date.now().toString();
      const newSession: Session = {
        id: sessionId,
        title: text.slice(0, 30) || 'Image Analysis',
        timestamp: Date.now(),
        mode: mode,
        data: null,
        history: [{ role: 'user', text: text || '[Image Uploaded]' }]
      };
      setSessions(prev => [newSession, ...prev]);
      setCurrentSessionId(sessionId);
    }

    try {
      let imageBase64: string | undefined;
      if (image) {
        imageBase64 = await new Promise((resolve) => {
          const reader = new FileReader();
          reader.onloadend = () => resolve(reader.result as string);
          reader.readAsDataURL(image);
        });
      }

      // Simulate multi-step pipeline messages for UX
      // Only update if we are still processing to avoid overwriting error/success states
      const t1 = setTimeout(() => {
        setProcessingState(p => p.status === 'processing' ? ({ ...p, message: 'Extracting knowledge graph...' }) : p);
      }, 1500);

      const t2 = setTimeout(() => {
        setProcessingState(p => p.status === 'processing' ? ({ ...p, message: `Generating ${mode.toLowerCase()} materials...` }) : p);
      }, 3000);

      timersRef.current.push(t1, t2);

      const result = await generateKnowSenseResponse(text, mode, imageBase64);

      clearTimers(); // Stop any pending messages

      // Update session with result
      setSessions(prev => prev.map(s => {
        if (s.id === sessionId) {
          return {
            ...s,
            data: result,
            title: result.summary.slice(0, 40) + "..." // Update title based on AI summary
          };
        }
        return s;
      }));
      setProcessingState({ status: 'success' });

    } catch (error) {
      clearTimers();
      console.error(error);
      setProcessingState({ 
        status: 'error', 
        message: 'Failed to process content. Please check your API Key and try again.' 
      });
    }
  };

  const currentSession = getCurrentSession();

  return (
    <div className="flex h-screen w-full bg-white">
      {/* Sidebar */}
      <Sidebar 
        sessions={sessions}
        currentSessionId={currentSessionId}
        onNewSession={handleNewSession}
        onSelectSession={handleSelectSession}
      />

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-full relative">
        <TopBar mode={mode} onModeChange={setMode} />

        <div className="flex-1 overflow-y-auto overflow-x-hidden p-6 relative">

          {/* Empty State */}
          {!currentSession && processingState.status === 'idle' && (
            <div className="h-full flex flex-col items-center justify-center text-center max-w-md mx-auto animate-in fade-in duration-700">
              <div className="w-16 h-16 bg-gray-50 rounded-2xl flex items-center justify-center mb-6 shadow-sm border border-gray-100">
                <Sparkles className="text-gray-400" size={32} />
              </div>
              <h2 className="text-2xl font-semibold text-gray-900 mb-3">What are we learning today?</h2>
              <p className="text-gray-500 mb-8">
                Paste notes, articles, or upload a photo of your textbook. 
                I'll extract the knowledge and create a study plan for you.
              </p>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 w-full text-sm">
                 <div className="p-3 border border-gray-200 rounded-lg text-gray-600 bg-white hover:border-gray-300 cursor-pointer transition-colors">
                    📄 Summarize PDF contents
                 </div>
                 <div className="p-3 border border-gray-200 rounded-lg text-gray-600 bg-white hover:border-gray-300 cursor-pointer transition-colors">
                    📝 Generate a quiz
                 </div>
              </div>
            </div>
          )}

          {/* Processing State */}
          {processingState.status === 'processing' && (
             <div className="h-full flex flex-col items-center justify-center">
                <Loader2 className="animate-spin text-gray-900 mb-4" size={40} />
                <p className="text-gray-500 font-medium animate-pulse">{processingState.message}</p>
             </div>
          )}

           {/* Error State */}
           {processingState.status === 'error' && (
             <div className="h-full flex flex-col items-center justify-center text-red-500">
                <AlertTriangle size={40} className="mb-4" />
                <p className="font-medium">{processingState.message}</p>
                <button 
                  onClick={() => setProcessingState({status: 'idle'})}
                  className="mt-4 text-sm text-gray-600 underline"
                >
                    Try Again
                </button>
             </div>
          )}

          {/* Result Display */}
          {currentSession?.data && processingState.status !== 'processing' && (
            <OutputRenderer data={currentSession.data} mode={currentSession.mode} />
          )}

        </div>

        {/* Floating Input Area (Sticky Bottom) */}
        <div className="bg-gradient-to-t from-white via-white to-transparent pb-6 pt-10 px-6 z-20">
          <InputBar onSend={handleSend} processingState={processingState} />
        </div>
      </div>
    </div>
  );
};

