import React, { useState, useEffect, useRef } from 'react';
import { Sidebar } from './components/Sidebar';
import { TopBar } from './components/TopBar';
import { InputBar } from './components/InputBar';
import { OutputRenderer } from './components/OutputRenderer';
import { UserMode, Session, ProcessingState } from './types';
import { generateKnowSenseResponse } from './services/gemini';
import { Loader2, Sparkles, AlertTriangle, X, Trash2, FileText, Check } from 'lucide-react';

// -- Sub-Components for Modals --

const Modal: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
  <div className="fixed inset-0 bg-black/20 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-in fade-in duration-200">
    <div className="bg-white rounded-xl shadow-2xl w-full max-w-md overflow-hidden">
      <div className="px-6 py-4 border-b border-gray-100 flex items-center justify-between">
        <h3 className="font-semibold text-gray-900">{title}</h3>
        <button onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors">
          <X size={20} />
        </button>
      </div>
      <div className="p-6">
        {children}
      </div>
    </div>
  </div>
);

const App: React.FC = () => {
  const [mode, setMode] = useState<UserMode>(UserMode.GENERAL);
  const [sessions, setSessions] = useState<Session[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [processingState, setProcessingState] = useState<ProcessingState>({ status: 'idle' });

  // Modal States
  const [showSettings, setShowSettings] = useState(false);
  const [showTemplates, setShowTemplates] = useState(false);

  const timersRef = useRef<NodeJS.Timeout[]>([]);

  // Load from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem('knowsense_sessions');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setSessions(parsed);
        if (parsed.length > 0) setCurrentSessionId(parsed[0].id);
      } catch (e) {
        console.error("Failed to load history", e);
      }
    }
  }, []);

  // Save to local storage on change
  useEffect(() => {
    localStorage.setItem('knowsense_sessions', JSON.stringify(sessions));
  }, [sessions]);

  useEffect(() => {
    return () => timersRef.current.forEach(clearTimeout);
  }, []);

  const clearTimers = () => {
    timersRef.current.forEach(clearTimeout);
    timersRef.current = [];
  };

  const handleNewSession = () => {
    setCurrentSessionId(null);
    setProcessingState({ status: 'idle' });
    clearTimers();
  };

  const handleSelectSession = (id: string) => {
    setCurrentSessionId(id);
    setProcessingState({ status: 'success' }); 
    clearTimers();
  };

  const clearHistory = () => {
    if (confirm("Are you sure you want to delete all sessions?")) {
      setSessions([]);
      setCurrentSessionId(null);
      setProcessingState({ status: 'idle' });
      setShowSettings(false);
    }
  };

  const handleSend = async (text: string, file?: File) => {
    clearTimers();
    setProcessingState({ status: 'processing', message: 'Analyzing content...' });

    // Determine attachment type logic
    const isPdf = file?.type === 'application/pdf';
    const isImage = file?.type.startsWith('image/');

    const fileLabel = file ? `[${isPdf ? 'PDF' : 'Image'} Uploaded: ${file.name}]` : '';
    const displayTitle = text ? text.slice(0, 30) : file?.name || 'New Session';

    let sessionId = currentSessionId;
    if (!sessionId) {
      sessionId = Date.now().toString();
      const newSession: Session = {
        id: sessionId,
        title: displayTitle,
        timestamp: Date.now(),
        mode: mode,
        data: null,
        history: [{ role: 'user', text: `${text} ${fileLabel}` }]
      };
      setSessions(prev => [newSession, ...prev]);
      setCurrentSessionId(sessionId);
    }

    try {
      let attachment: { base64: string; mimeType: string } | undefined;

      if (file) {
        const base64String = await new Promise<string>((resolve, reject) => {
          const reader = new FileReader();
          reader.onloadend = () => resolve(reader.result as string);
          reader.onerror = reject;
          reader.readAsDataURL(file);
        });

        attachment = {
          base64: base64String,
          mimeType: file.type
        };
      }

      // UX Timers
      const t1 = setTimeout(() => {
        setProcessingState(p => p.status === 'processing' ? ({ ...p, message: isPdf ? 'Reading document pages...' : 'Extracting knowledge graph...' }) : p);
      }, 1500);

      const t2 = setTimeout(() => {
        setProcessingState(p => p.status === 'processing' ? ({ ...p, message: `Generating ${mode.toLowerCase()} materials...` }) : p);
      }, 3000);

      timersRef.current.push(t1, t2);

      const result = await generateKnowSenseResponse(text, mode, attachment);

      clearTimers();

      setSessions(prev => prev.map(s => {
        if (s.id === sessionId) {
          return {
            ...s,
            data: result,
            title: result.summary.slice(0, 40) + "..."
          };
        }
        return s;
      }));
      setProcessingState({ status: 'success' });

    } catch (error) {
      clearTimers();
      console.error(error);
      setProcessingState({ 
        status: 'error', 
        message: 'Failed to process content. Ensure your API Key is valid and the file size is reasonable.' 
      });
    }
  };

  const handleTemplateClick = (templateText: string) => {
    setShowTemplates(false);
    handleSend(templateText);
  };

  const currentSession = sessions.find(s => s.id === currentSessionId);

  return (
    <div className="flex h-screen w-full bg-white">
      {/* Sidebar */}
      <Sidebar 
        sessions={sessions}
        currentSessionId={currentSessionId}
        onNewSession={handleNewSession}
        onSelectSession={handleSelectSession}
        onOpenSettings={() => setShowSettings(true)}
        onOpenTemplates={() => setShowTemplates(true)}
      />

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-full relative">
        <TopBar mode={mode} onModeChange={setMode} />

        <div className="flex-1 overflow-y-auto overflow-x-hidden p-6 relative">

          {/* Empty State */}
          {!currentSession && processingState.status === 'idle' && (
            <div className="h-full flex flex-col items-center justify-center text-center max-w-md mx-auto animate-in fade-in duration-700">
              <div className="w-16 h-16 bg-gray-50 rounded-2xl flex items-center justify-center mb-6 shadow-sm border border-gray-100">
                <Sparkles className="text-gray-400" size={32} />
              </div>
              <h2 className="text-2xl font-semibold text-gray-900 mb-3">What are we learning today?</h2>
              <p className="text-gray-500 mb-8">
                Paste notes, articles, or upload a photo of your textbook (or a PDF!). 
                I'll extract the knowledge and create a study plan for you.
              </p>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 w-full text-sm">
                 <button onClick={() => handleSend("Create a quiz about photosynthesis")} className="p-3 border border-gray-200 rounded-lg text-gray-600 bg-white hover:border-gray-300 transition-colors text-left">
                    🌱 Quiz on Photosynthesis
                 </button>
                 <button onClick={() => handleSend("Explain Quantum Entanglement simply")} className="p-3 border border-gray-200 rounded-lg text-gray-600 bg-white hover:border-gray-300 transition-colors text-left">
                    ⚛️ Quantum Physics Basics
                 </button>
              </div>
            </div>
          )}

          {/* Processing State */}
          {processingState.status === 'processing' && (
             <div className="h-full flex flex-col items-center justify-center">
                <Loader2 className="animate-spin text-gray-900 mb-4" size={40} />
                <p className="text-gray-500 font-medium animate-pulse">{processingState.message}</p>
             </div>
          )}

           {/* Error State */}
           {processingState.status === 'error' && (
             <div className="h-full flex flex-col items-center justify-center text-red-500">
                <AlertTriangle size={40} className="mb-4" />
                <p className="font-medium">{processingState.message}</p>
                <button 
                  onClick={() => setProcessingState({status: 'idle'})}
                  className="mt-4 text-sm text-gray-600 underline"
                >
                    Try Again
                </button>
             </div>
          )}

          {/* Result Display */}
          {currentSession?.data && processingState.status !== 'processing' && (
            <OutputRenderer data={currentSession.data} mode={currentSession.mode} />
          )}

        </div>

        {/* Floating Input Area (Sticky Bottom) */}
        <div className="bg-gradient-to-t from-white via-white to-transparent pb-6 pt-10 px-6 z-20">
          <InputBar onSend={handleSend} processingState={processingState} />
        </div>
      </div>

      {/* Settings Modal */}
      {showSettings && (
        <Modal title="Settings" onClose={() => setShowSettings(false)}>
          <div className="space-y-4">
            <div>
              <h4 className="text-sm font-medium text-gray-700 mb-2">Data Management</h4>
              <button 
                onClick={clearHistory}
                className="w-full flex items-center justify-center gap-2 px-4 py-2 bg-red-50 text-red-600 rounded-lg hover:bg-red-100 transition-colors text-sm font-medium"
              >
                <Trash2 size={16} />
                Clear All History
              </button>
              <p className="text-xs text-gray-400 mt-2 text-center">
                This will remove all your saved sessions from this browser.
              </p>
            </div>
          </div>
        </Modal>
      )}

      {/* Templates Modal */}
      {showTemplates && (
        <Modal title="Quick Start Templates" onClose={() => setShowTemplates(false)}>
          <div className="grid gap-3">
            {[
              { icon: "🧬", text: "Explain DNA replication structure" },
              { icon: "🏛️", text: "Key events of the French Revolution" },
              { icon: "💻", text: "React Hooks explained for beginners" },
              { icon: "📈", text: "Marketing strategies for startups" }
            ].map((t, i) => (
              <button 
                key={i}
                onClick={() => handleTemplateClick(t.text)}
                className="flex items-center gap-3 p-3 rounded-lg border border-gray-200 hover:bg-gray-50 transition-colors text-left"
              >
                <span className="text-xl">{t.icon}</span>
                <span className="text-sm text-gray-700 font-medium">{t.text}</span>
              </button>
            ))}
          </div>
        </Modal>
      )}

    </div>
  );
};

export default App;

import React, { useRef, useState, useEffect } from 'react';
import { ArrowUp, Image as ImageIcon, X, Paperclip, FileText, ChevronUp } from 'lucide-react';
import { ProcessingState } from '../types';

interface InputBarProps {
  onSend: (text: string, file?: File) => void;
  processingState: ProcessingState;
}

export const InputBar: React.FC<InputBarProps> = ({ onSend, processingState }) => {
  const [text, setText] = useState('');
  const [file, setFile] = useState<File | null>(null);
  const [showAttachMenu, setShowAttachMenu] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowAttachMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit();
    }
  };

  const handleSubmit = () => {
    if ((!text.trim() && !file) || processingState.status === 'processing') return;
    onSend(text, file || undefined);
    setText('');
    setFile(null);
    if (textareaRef.current) {
        textareaRef.current.style.height = 'auto';
    }
  };

  const handleFileSelect = (acceptType: string) => {
    if (fileInputRef.current) {
      fileInputRef.current.value = ''; // CRITICAL FIX: Reset input so same file can be selected again
      fileInputRef.current.accept = acceptType;
      fileInputRef.current.click();
    }
    setShowAttachMenu(false);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
    }
  };

  const adjustHeight = (e: React.FormEvent<HTMLTextAreaElement>) => {
    const target = e.currentTarget;
    target.style.height = 'auto';
    target.style.height = `${Math.min(target.scrollHeight, 200)}px`;
  };

  const getFileIcon = (f: File) => {
    if (f.type.includes('pdf')) return <FileText size={14} className="text-red-500" />;
    return <ImageIcon size={14} className="text-blue-500" />;
  };

  return (
    <div className="w-full max-w-3xl mx-auto p-4 mb-4">
      {/* File Preview */}
      {file && (
        <div className="mb-2 inline-flex items-center gap-2 bg-gray-100 px-3 py-1.5 rounded-full text-xs font-medium text-gray-700 animate-in fade-in slide-in-from-bottom-2 border border-gray-200">
          {getFileIcon(file)}
          <span className="max-w-[200px] truncate">{file.name}</span>
          <button 
            onClick={() => setFile(null)}
            className="hover:bg-gray-200 rounded-full p-0.5 ml-1 transition-colors"
          >
            <X size={12} />
          </button>
        </div>
      )}

      {/* Input Box */}
      <div className={`relative bg-white border shadow-sm rounded-xl transition-all ${processingState.status === 'processing' ? 'border-gray-200 opacity-75' : 'border-gray-300 hover:border-gray-400 focus-within:ring-2 focus-within:ring-gray-100 focus-within:border-gray-400'}`}>
        <textarea
            ref={textareaRef}
            value={text}
            onChange={(e) => { setText(e.target.value); adjustHeight(e); }}
            onKeyDown={handleKeyDown}
            placeholder="Paste text, notes, or attach a file..."
            rows={1}
            disabled={processingState.status === 'processing'}
            className="w-full px-4 py-3.5 pr-20 bg-transparent resize-none outline-none text-gray-800 placeholder-gray-400 min-h-[52px] max-h-[200px]"
        />

        <div className="absolute bottom-2.5 right-2 flex items-center gap-1">
             <input
                type="file"
                ref={fileInputRef}
                onChange={handleFileChange}
                className="hidden"
            />

            <div className="relative" ref={menuRef}>
              <button
                  onClick={() => setShowAttachMenu(!showAttachMenu)}
                  disabled={processingState.status === 'processing'}
                  className={`p-2 rounded-lg transition-colors ${showAttachMenu ? 'bg-gray-100 text-gray-900' : 'text-gray-400 hover:text-gray-600 hover:bg-gray-100'}`}
                  title="Attach"
              >
                  <Paperclip size={18} />
              </button>

              {showAttachMenu && (
                <div className="absolute bottom-full right-0 mb-2 w-48 bg-white border border-gray-200 rounded-lg shadow-xl py-1 z-30 animate-in fade-in zoom-in-95 duration-100 origin-bottom-right">
                  <div className="px-3 py-2 text-xs font-semibold text-gray-400 uppercase tracking-wider border-b border-gray-100 mb-1">
                    Attach Resource
                  </div>
                  <button 
                    onClick={() => handleFileSelect('image/*')}
                    className="w-full text-left px-4 py-2.5 text-sm hover:bg-gray-50 flex items-center gap-3 text-gray-700"
                  >
                    <ImageIcon size={16} className="text-blue-500" />
                    Upload Image
                  </button>
                  <button 
                    onClick={() => handleFileSelect('application/pdf')}
                    className="w-full text-left px-4 py-2.5 text-sm hover:bg-gray-50 flex items-center gap-3 text-gray-700"
                  >
                    <FileText size={16} className="text-red-500" />
                    Upload PDF
                  </button>
                </div>
              )}
            </div>

            <button
                onClick={handleSubmit}
                disabled={(!text.trim() && !file) || processingState.status === 'processing'}
                className={`p-2 rounded-lg transition-all ${
                    (!text.trim() && !file) || processingState.status === 'processing'
                    ? 'bg-gray-100 text-gray-300' 
                    : 'bg-black text-white hover:bg-gray-800 shadow-sm'
                }`}
            >
                <ArrowUp size={18} />
            </button>
        </div>
      </div>
      <div className="text-center mt-2">
         <p className="text-[10px] text-gray-400">Supports Images (PNG, JPG) and Documents (PDF).</p>
      </div>
    </div>
  );
};

